import { cn } from '@/lib/utils'
import { asset } from '@/lib/base'

const art = {
  circuit: '/bg/circuit.svg',
  code: '/bg/code.svg',
  network: '/bg/network.svg',
} as const

/**
 * Technology background art behind a section: circuit traces, real code, or a node graph
 * (generated by `npm run backgrounds`, original artwork). Decorative, faded at the edges, kept
 * faint so text contrast is unaffected, and it drifts slightly with scroll ([data-parallax]).
 * The parent section needs `relative isolate overflow-hidden`.
 */
export function TechBackdrop({ kind, className }: { kind: keyof typeof art; className?: string }) {
  return (
    <div
      aria-hidden
      data-parallax="0.15"
      className={cn(
        'pointer-events-none absolute inset-x-0 -inset-y-[12%] -z-10 bg-cover bg-center bg-no-repeat opacity-[0.16] dark:opacity-[0.22]',
        className,
      )}
      style={{ backgroundImage: `url(${asset(art[kind])})` }}
    />
  )
}
